package fun.hymnmusic.team;

import android.app.Activity;
import android.app.AlertDialog;
import android.app.DatePickerDialog;
import android.app.TimePickerDialog;
import android.content.ClipData;
import android.content.ClipboardManager;
import android.content.Context;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.Gravity;
import android.view.View;
import android.view.WindowManager;
import android.widget.Button;
import android.widget.CheckBox;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.Spinner;
import android.widget.ArrayAdapter;
import android.widget.TextView;
import org.json.JSONArray;
import org.json.JSONObject;
import java.util.Calendar;
import java.util.UUID;
import java.util.concurrent.ExecutorService;

/** Native, permission-scoped artist context. The activity editor remains attached underneath. */
final class ArtistJourneyDialog {
    private final Activity activity;
    private final TeamApi api;
    private final ExecutorService io;
    private final TeamPalette palette;
    private final String workspace, taskId, activityId;
    private final boolean editable, canEmail;
    private AlertDialog dialog;
    private LinearLayout body;
    private TextView status;
    private boolean busy;
    private JSONObject data;
    interface OpenActivity { void open(JSONObject item); }
    private OpenActivity opener;
    private String promiseKey=UUID.randomUUID().toString(), recapKey=UUID.randomUUID().toString(), mailKey=UUID.randomUUID().toString();

    ArtistJourneyDialog(Activity activity, TeamApi api, ExecutorService io, TeamPalette palette, String workspace, String taskId, String activityId, boolean editable, boolean canEmail) {
        this.activity=activity;this.api=api;this.io=io;this.palette=palette;this.workspace=workspace;this.taskId=taskId;this.activityId=activityId;this.editable=editable;this.canEmail=canEmail;
    }
    void show() {
        ScrollView scroll=new ScrollView(activity);scroll.setFillViewport(true);scroll.setClipToPadding(false);
        body=new LinearLayout(activity);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(20),dp(16),dp(20),dp(24));body.setBackgroundColor(palette.background);scroll.addView(body,new ScrollView.LayoutParams(-1,-2));
        dialog=new AlertDialog.Builder(activity).setTitle("Artist journey").setView(scroll).setNegativeButton("Back to activity",null).create();
        dialog.setOnShowListener(d->{if(dialog.getWindow()!=null)dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);});
        dialog.show();load();
    }
    static void showDesk(Activity activity,TeamApi api,ExecutorService io,TeamPalette palette,String workspace,OpenActivity opener){ArtistJourneyDialog view=new ArtistJourneyDialog(activity,api,io,palette,workspace,"","",false,false);view.opener=opener;view.show();view.dialog.setTitle("Artist success desk");}
    private void load() {
        body.removeAllViews();label(body,"Preparing artist context…",14,false);
        io.execute(()->{try{JSONObject response=api.get(taskId.isEmpty()?"artist-desk":"artist-activity",workspace,taskId.isEmpty()?"":"id="+java.net.URLEncoder.encode(taskId,"UTF-8"));activity.runOnUiThread(()->{if(dialog.isShowing()){data=response;render();}});}catch(Exception e){activity.runOnUiThread(()->{if(!dialog.isShowing())return;body.removeAllViews();label(body,"Artist context could not be loaded. Your call notes remain in the activity.",14,false);label(body,e.getMessage(),12,false);Button retry=button(body,"Retry",false);retry.setOnClickListener(v->load());});}});
    }
    private void render() {
        if(taskId.isEmpty()){renderDesk();return;}
        body.removeAllViews();status=label(body,"Your goal, one useful next step, and promises kept.",13,false);
        JSONObject insight=data.optJSONObject("insight");
        if(insight==null){label(body,"Link a registered artist account to use shared journeys.",14,false);if(canEmail){Button email=button(body,"Email the customer",false);email.setOnClickListener(v->composeMail("Your HYMN follow-up","Thank you for connecting with HYMN. Please reply with your current priority and any questions."));}return;}
        JSONObject p=insight.optJSONObject("profile"),score=insight.optJSONObject("score");
        LinearLayout brief=card(body);label(brief,insight.optString("goal","Artist’s next step"),20,true);label(brief,"Current blocker",11,true);label(brief,insight.optString("blocker"),14,false);label(brief,"Useful next step",11,true);label(brief,insight.optString("suggestion"),14,false);
        if(p!=null){label(brief,"Contact: "+p.optString("contact").replace('_',' ')+" · "+p.optString("mode"),12,true);if(p.optString("contact").equals("CALL"))label(brief,p.optInt("startHour")+":00–"+p.optInt("endHour")+":00 · "+p.optString("timezone"),12,false);if(!p.optString("notes").isEmpty())label(brief,"Artist’s words: "+p.optString("notes"),13,false);}
        if(score!=null){label(brief,"Recent engagement: "+score.optInt("score")+"/100",12,true);label(brief,"Engagement is an observation, not proof of purchase intent.",12,false);}
        LinearLayout listening=section("Listening and shortlist");JSONArray listens=insight.optJSONArray("listens");
        if(p==null||!p.optBoolean("analytics"))label(listening,"The artist has not shared listening insights.",13,false);
        else if(listens==null||listens.length()==0)label(listening,"No recent shared listening sessions.",13,false);
        else for(int n=0;n<listens.length();n++){JSONObject l=listens.optJSONObject(n);if(l==null)continue;LinearLayout row=card(listening);label(row,l.optString("title","Beat #"+l.optInt("beatId")),15,true);label(row,Math.round(l.optDouble("seconds"))+"s playback · "+Math.round(l.optDouble("uniqueSeconds"))+"s unique · "+l.optInt("sessions")+" sessions",12,false);}
        JSONArray shortlist=p==null?new JSONArray():p.optJSONArray("shortlist");if(shortlist!=null&&shortlist.length()>0)label(listening,"Shortlisted beat IDs: "+shortlist.toString(),12,true);
        LinearLayout readiness=section("Release readiness");JSONArray releases=insight.optJSONArray("readiness");if(releases==null||releases.length()==0)label(readiness,"No unfinished release requirements found.",13,false);else for(int n=0;n<releases.length();n++){JSONObject r=releases.optJSONObject(n);if(r==null)continue;label(readiness,r.optString("title","Release")+" · "+r.optString("status").replace('_',' '),15,true);JSONArray checks=r.optJSONArray("checks");if(checks!=null)for(int j=0;j<checks.length();j++){JSONObject c=checks.optJSONObject(j);if(c!=null)label(readiness,(c.optBoolean("done")?"✓ ":"○ ")+c.optString("label"),13,false);}}label(readiness,"Completeness is separate from final approval.",12,false);
        LinearLayout promises=section("Promises and deadlines");JSONArray rows=data.optJSONArray("promises");if(rows==null||rows.length()==0)label(promises,"Add only actions actually agreed with the artist.",13,false);else for(int n=0;n<rows.length();n++){JSONObject item=rows.optJSONObject(n);if(item==null)continue;LinearLayout row=card(promises);label(row,item.optString("party")+" · "+item.optString("status").replace('_',' '),11,true);label(row,item.optString("text"),15,true);label(row,"Due "+item.optString("dueAt"),12,false);if(editable&&item.optBoolean("canComplete",true)&&!item.optString("status").equals("DONE")){Button done=button(row,"Confirm completed",false);done.setOnClickListener(v->completePromise(item));}}
        if(editable){Button add=button(promises,"Add agreed action",true);add.setOnClickListener(v->newPromise());Button recap=button(body,"Write a reviewed recap",true);recap.setOnClickListener(v->newRecap(shortlist));}
        if(canEmail){Button email=button(body,"Email the customer",false);email.setOnClickListener(v->composeMail("Your HYMN follow-up","Thank you for connecting with HYMN. Please reply with your current priority and any questions so we can help you choose the next step."));}
        JSONArray recaps=data.optJSONArray("recaps");if(recaps!=null&&recaps.length()>0){LinearLayout history=section("Shared session recaps");for(int n=0;n<recaps.length();n++){JSONObject r=recaps.optJSONObject(n);if(r!=null){label(history,r.optString("senderName"),12,true);label(history,r.optString("summary"),14,false);label(history,"Next steps: "+r.optString("nextSteps"),13,false);}}}
    }
    private void renderDesk(){body.removeAllViews();label(body,"Help the next artist move forward.",22,true);label(body,"Useful context, one owner and promises kept.",13,false);JSONObject counts=data.optJSONObject("promises");if(counts!=null){LinearLayout metrics=card(body);label(metrics,counts.optInt("open")+" open promises · "+counts.optInt("overdue")+" need attention · "+counts.optInt("done")+" kept",15,true);}JSONArray items=data.optJSONArray("items");if(items==null||items.length()==0)label(body,"New artist requests and useful follow-ups appear here automatically.",14,false);else for(int n=0;n<items.length();n++){JSONObject item=items.optJSONObject(n);if(item==null)continue;LinearLayout row=card(body);label(row,item.optString("title"),17,true);label(row,item.optString("reason"),13,false);label(row,item.optString("nextStep"),13,false);Button open=button(row,"Open activity",true);open.setOnClickListener(v->{dialog.dismiss();if(opener!=null)opener.open(item);});}Button refresh=button(body,"Refresh priorities",false);refresh.setOnClickListener(v->load());}
    private void newPromise(){LinearLayout form=column();EditText text=input(form,"Agreed action",2);Spinner party=choices(form,"Who committed?",new String[]{"HYMN team","Artist"});Calendar when=Calendar.getInstance();when.add(Calendar.DAY_OF_YEAR,1);label(form,"Deadline (your device timezone)",12,true);Button due=button(form,java.text.DateFormat.getDateTimeInstance().format(when.getTime()),false);due.setOnClickListener(v->new DatePickerDialog(activity,(picker,y,m,d)->{when.set(y,m,d);new TimePickerDialog(activity,(time,h,min)->{when.set(Calendar.HOUR_OF_DAY,h);when.set(Calendar.MINUTE,min);when.set(Calendar.SECOND,0);due.setText(java.text.DateFormat.getDateTimeInstance().format(when.getTime()));},when.get(Calendar.HOUR_OF_DAY),when.get(Calendar.MINUTE),true).show();},when.get(Calendar.YEAR),when.get(Calendar.MONTH),when.get(Calendar.DAY_OF_MONTH)).show());
        formDialog("Add agreed action",form,"Save action",()->{if(text.getText().toString().trim().length()<3)throw new Exception("Describe the agreed action.");return new JSONObject().put("id",promiseKey).put("taskId",taskId).put("version",0).put("text",text.getText().toString().trim()).put("party",party.getSelectedItemPosition()==0?"HYMN":"ARTIST").put("dueAt",when.toInstant().toString()).put("evidence","MANUAL");},"artist-promise-save",result->{promiseKey=UUID.randomUUID().toString();load();});}
    private void completePromise(JSONObject item){LinearLayout form=column();EditText evidence=input(form,"What confirms completion?",3);formDialog("Completion evidence",form,"Confirm",()->new JSONObject().put("taskId",item.optString("taskId")).put("id",item.optString("id")).put("version",item.optInt("version")).put("evidence",evidence.getText().toString().trim()),"artist-promise-complete",r->load());}
    private void newRecap(JSONArray shortlist){LinearLayout form=column();label(form,"Share useful advice and agreed steps. Internal call notes are not copied.",13,false);EditText summary=input(form,"Conversation summary",4),steps=input(form,"Agreed next steps",3);CheckBox reviewed=new CheckBox(activity);reviewed.setText("I reviewed this customer-facing recap.");reviewed.setTextColor(palette.text);form.addView(reviewed);watchReview(reviewed,()->recapKey=UUID.randomUUID().toString(),summary,steps);formDialog("Session recap",form,"Publish recap",()->{if(!reviewed.isChecked())throw new Exception("Review the recap before publishing.");return new JSONObject().put("taskId",taskId).put("requestKey",recapKey).put("summary",summary.getText().toString().trim()).put("nextSteps",steps.getText().toString().trim()).put("beatIds",shortlist==null?new JSONArray():shortlist).put("reviewed",true);},"artist-recap-publish",r->{recapKey=UUID.randomUUID().toString();String link=TeamApi.BASE+r.optString("url");if(canEmail)composeMail("Your HYMN session recap",summary.getText()+"\n\nNext steps\n"+steps.getText()+"\n\nOpen your private recap: "+link);else{((ClipboardManager)activity.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Private artist recap",link));load();}});}
    private void composeMail(String initialSubject,String initialBody){JSONObject client=data.optJSONObject("client");String recipient=client==null?"":client.optString("email");LinearLayout form=column();label(form,"To: "+(recipient.isEmpty()?"Add the customer’s email to their contact first.":recipient),13,true);label(form,"Standard HYMN design. Your name and role are added automatically.",12,false);final String[] mailKind={"followup"};JSONObject templates=data.optJSONObject("emailTemplates"),names=data.optJSONObject("emailLabels");java.util.ArrayList<String> keys=new java.util.ArrayList<>(),labels=new java.util.ArrayList<>();keys.add("followup");labels.add("Current draft");if(templates!=null){java.util.Iterator<String> it=templates.keys();while(it.hasNext()){String key=it.next();if(key.equals("missed-call"))continue;keys.add(key);labels.add(names==null?key:names.optString(key,key));}}Spinner template=choices(form,"Template",labels.toArray(new String[0]));EditText subject=input(form,"Subject",1);subject.setText(initialSubject);EditText message=input(form,"Message",6);message.setText(initialBody);template.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> parent){} public void onItemSelected(android.widget.AdapterView<?> parent,View view,int position,long id){mailKind[0]=keys.get(position);JSONObject model=templates==null?null:templates.optJSONObject(mailKind[0]);subject.setText(position==0?initialSubject:model==null?initialSubject:model.optString("subject"));message.setText(position==0?initialBody:model==null?initialBody:model.optString("body"));}});CheckBox reviewed=new CheckBox(activity);reviewed.setText("I reviewed the recipient, message and next steps.");reviewed.setTextColor(palette.text);form.addView(reviewed);watchReview(reviewed,()->mailKey=UUID.randomUUID().toString(),subject,message);formDialog("Email the customer",form,"Queue email",()->{if(!reviewed.isChecked()||recipient.isEmpty())throw new Exception("Check the recipient and review the message.");return new JSONObject().put("id",taskId).put("activityId",activityId).put("requestKey",mailKey).put("kind",mailKind[0]).put("recipient",recipient).put("subject",subject.getText().toString().trim()).put("body",message.getText().toString().trim()).put("reviewed",true);},"workstation-email",r->{mailKey=UUID.randomUUID().toString();status.setText(r.optString("reason","Email "+r.optString("status","queued").toLowerCase()+". Your activity notes are unchanged."));});}
    private void watchReview(CheckBox reviewed,Runnable changed,EditText... fields){for(EditText field:fields)field.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){} public void onTextChanged(CharSequence s,int start,int before,int count){reviewed.setChecked(false);changed.run();} public void afterTextChanged(android.text.Editable e){} });}
    private interface Payload{JSONObject get() throws Exception;}
    private interface Success{void done(JSONObject result);}
    private void formDialog(String title,LinearLayout form,String action,Payload payload,String resource,Success success){ScrollView scroll=new ScrollView(activity);scroll.addView(form);AlertDialog editor=new AlertDialog.Builder(activity).setTitle(title).setView(scroll).setNegativeButton("Cancel",null).setPositiveButton(action,null).create();editor.setOnShowListener(d->{if(editor.getWindow()!=null)editor.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);editor.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(busy)return;final JSONObject request;try{request=payload.get();}catch(Exception e){new AlertDialog.Builder(activity).setMessage(e.getMessage()).setPositiveButton("OK",null).show();return;}busy=true;editor.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);io.execute(()->{try{JSONObject result=api.post(resource,workspace,request);activity.runOnUiThread(()->{busy=false;if(!dialog.isShowing())return;editor.dismiss();success.done(result);});}catch(Exception e){activity.runOnUiThread(()->{busy=false;if(!editor.isShowing())return;editor.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);new AlertDialog.Builder(activity).setTitle("Please review").setMessage(e.getMessage()).setPositiveButton("OK",null).show();});}});});});editor.show();}
    private LinearLayout column(){LinearLayout l=new LinearLayout(activity);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(20),dp(12),dp(20),dp(20));l.setBackgroundColor(palette.background);return l;}
    private LinearLayout card(LinearLayout parent){LinearLayout row=column();GradientDrawable bg=new GradientDrawable();bg.setColor(palette.card);bg.setCornerRadius(dp(14));bg.setStroke(dp(1),palette.border);row.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(14);parent.addView(row,lp);return row;}
    private LinearLayout section(String title){LinearLayout wrapper=card(body);Button toggle=button(wrapper,title+"  +",false);LinearLayout content=new LinearLayout(activity);content.setOrientation(LinearLayout.VERTICAL);content.setVisibility(View.GONE);wrapper.addView(content);toggle.setOnClickListener(v->{boolean open=content.getVisibility()==View.VISIBLE;content.setVisibility(open?View.GONE:View.VISIBLE);toggle.setText(title+(open?"  +":"  −"));});return content;}
    private TextView label(LinearLayout parent,String value,int size,boolean bold){TextView t=new TextView(activity);t.setText(value==null?"":value);t.setTextSize(size);t.setTextColor(bold?palette.text:palette.muted);t.setTypeface(Typeface.DEFAULT,bold?Typeface.BOLD:Typeface.NORMAL);t.setLineSpacing(dp(3),1);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(10);parent.addView(t,lp);return t;}
    private Button button(LinearLayout parent,String title,boolean primary){Button b=new Button(activity);b.setText(title);b.setAllCaps(false);b.setTextSize(14);b.setMinHeight(dp(48));b.setTextColor(primary?palette.accentForeground:palette.text);GradientDrawable bg=new GradientDrawable();bg.setColor(primary?palette.accent:palette.card);bg.setCornerRadius(dp(12));bg.setStroke(dp(1),palette.border);b.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(12);parent.addView(b,lp);return b;}
    private EditText input(LinearLayout parent,String title,int lines){label(parent,title,12,true);EditText input=new EditText(activity);input.setTextColor(palette.text);input.setHintTextColor(palette.muted);input.setTextSize(16);input.setMinLines(lines);input.setGravity(Gravity.TOP);input.setPadding(dp(12),dp(12),dp(12),dp(12));input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|(lines>1?android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE:0));GradientDrawable bg=new GradientDrawable();bg.setColor(palette.card);bg.setCornerRadius(dp(10));bg.setStroke(dp(1),palette.border);input.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(8);parent.addView(input,lp);return input;}
    private Spinner choices(LinearLayout parent,String title,String[] values){label(parent,title,12,true);Spinner spinner=new Spinner(activity);spinner.setAdapter(new ArrayAdapter<String>(activity,android.R.layout.simple_spinner_dropdown_item,values){@Override public View getView(int position,View convert,android.view.ViewGroup parent){TextView view=(TextView)super.getView(position,convert,parent);view.setTextColor(palette.text);view.setBackgroundColor(palette.card);view.setTextSize(15);return view;}@Override public View getDropDownView(int position,View convert,android.view.ViewGroup parent){TextView view=(TextView)super.getDropDownView(position,convert,parent);view.setTextColor(palette.text);view.setBackgroundColor(palette.card);view.setPadding(dp(12),dp(12),dp(12),dp(12));return view;}});parent.addView(spinner,new LinearLayout.LayoutParams(-1,dp(48)));return spinner;}
    private int dp(int value){return Math.round(activity.getResources().getDisplayMetrics().density*value);}
}
